import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.sf.jsqlparser.JSQLParserException;
import net.sf.jsqlparser.expression.ExpressionVisitorAdapter;
import net.sf.jsqlparser.parser.CCJSqlParserUtil;
import net.sf.jsqlparser.statement.Statement;
import net.sf.jsqlparser.statement.select.Select;
import net.sf.jsqlparser.util.SelectUtils;
import net.sf.jsqlparser.util.deparser.ExpressionDeParser;

public String convertToPageSql(String sql, Integer offset, Integer limit) {
    Statement stmt;
    try {
        stmt = CCJSqlParserUtil.parse(sql);
    } catch (JSQLParserException e) {
        throw new PageException("不支持该SQL转换为分页查询!", e);
    }
    if (!(stmt instanceof Select)) {
        throw new PageException("分页语句必须是Select查询!");
    }

    // Get the page select
    Select pageSelect = (Select) stmt;

    // Replace offset and limit parameters
    pageSelect = SelectUtils.replaceTopInSelect(pageSelect, null);

    if (offset != null) {
        pageSelect.getSelectBody().accept(new OffsetVisitor(offset));
    }
    if (limit != null) {
        pageSelect.getSelectBody().accept(new LimitVisitor(limit));
    }

    return pageSelect.toString();
}

class OffsetVisitor extends ExpressionDeParser {
    private int offset;
    private boolean inOffset = false;

    public OffsetVisitor(int offset) {
        this.offset = offset;
    }

    @Override
    public void visit(Pattern p) {
        inOffset = true;
        super.visit(p);
        inOffset = false;
    }

    @Override
    public void visit(String s) {
        if (inOffset) {
            this.buffer.replace(this.buffer.length() - s.length(), this.buffer.length(), Integer.toString(offset));
        } else {
            super.visit(s);
        }
    }
}

class LimitVisitor extends ExpressionVisitorAdapter {
    private int limit;

    public LimitVisitor(int limit) {
        this.limit = limit;
    }

    @Override
    public void visit(Pattern p) {
        p.setRowsOnly(true);
        p.setRowCountJdbcParameter(null);
        p.setRowCount(limit);
    }
}

